components.css:
.pp-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 40px;
  padding: 0 16px;
  border-radius: 4px;
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  line-height: 1.4;
  cursor: pointer;
  transition: background-color 120ms var(--ease-out-quart), box-shadow 120ms var(--ease-out-quart);
}
.pp-btn--primary {
  color: var(--on-accent);
  background: var(--accent);
  border: 1px solid var(--accent-hover);
  box-shadow: var(--elevation-sm);
}
.pp-btn--primary:hover { background: var(--accent-hover); }
.pp-btn--primary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; box-shadow: var(--glow-gold); }
.pp-btn--primary:active { background: var(--accent-hover); box-shadow: var(--glow-gold-strong); }
.pp-btn--primary:disabled { opacity: .4; cursor: not-allowed; box-shadow: none; border-color: var(--border-subtle); }

.pp-btn--secondary {
  color: var(--accent);
  background: transparent;
  border: 1px solid var(--accent);
}
.pp-btn--secondary:hover { background: var(--accent-subtle); }
.pp-btn--secondary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.pp-btn--secondary:active { background: var(--accent-subtle); }
.pp-btn--secondary:disabled { opacity: .4; cursor: not-allowed; border-color: var(--border-subtle); color: var(--text-faint); }

.pp-field { display: grid; gap: 6px; }
.pp-field__label { font-family: var(--font-body); font-size: 13px; font-weight: 500; color: var(--text); }
.pp-field__input {
  width: 100%;
  min-height: 96px;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 4px;
  background: var(--surface);
  color: var(--text);
  font-family: var(--font-body);
  font-size: 13px;
  line-height: 1.4;
  resize: vertical;
  transition: border-color 120ms var(--ease-out-quart), box-shadow 120ms var(--ease-out-quart);
}
.pp-field__input:hover { border-color: var(--border-strong); }
.pp-field__input:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 25%, transparent); }
.pp-field__input:disabled { background: var(--bg-sunken); color: var(--text-faint); cursor: not-allowed; }

.pp-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 24px;
  padding: 0 10px;
  border: 1px solid var(--border);
  border-radius: 2px;
  background: var(--surface);
  color: var(--text-muted);
  font-family: var(--font-body);
  font-size: 12px;
  line-height: 1.4;
  white-space: nowrap;
}
.pp-chip__dot { width: 6px; height: 6px; border-radius: 9999px; background: currentColor; }
.pp-chip--success { background: var(--tint-green); border-color: transparent; color: var(--success); }
.pp-chip--error { background: var(--tint-red); border-color: transparent; color: var(--danger); }
.pp-chip--info { background: var(--tint-purple); border-color: transparent; color: var(--info); }

.pp-card {
  padding: 20px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--surface);
  box-shadow: var(--elevation-sm);
}
.pp-card__title { margin: 0 0 8px; font-family: var(--font-display); font-size: 18px; font-weight: 600; line-height: 1.35; color: var(--text); }
.pp-card__body { margin: 0; max-width: 68ch; font-family: var(--font-body); font-size: 15px; line-height: 1.7; color: var(--text-muted); }

.pp-nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 40px;
  padding: 0 10px;
  border: 1px solid transparent;
  border-radius: 4px;
  color: var(--text-muted);
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  text-decoration: none;
  transition: background-color 120ms var(--ease-out-quart), color 120ms var(--ease-out-quart);
}
.pp-nav-item:hover { background: var(--surface-raised); color: var(--text); }
.pp-nav-item--active { background: var(--accent-subtle); border-color: var(--accent); color: var(--accent); box-shadow: var(--glow-gold); }
.pp-nav-item:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.pp-rating { display: inline-flex; align-items: center; gap: 8px; }
.pp-rating__stars { display: inline-flex; gap: 2px; }
.pp-rating__star { display: inline-flex; padding: 2px; border: 0; background: transparent; color: var(--border-strong); cursor: pointer; }
.pp-rating__star svg { width: 18px; height: 18px; }
.pp-rating__star.is-on { color: var(--accent); }
.pp-rating__star:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 2px; }
.pp-rating__label { font-family: var(--font-body); font-size: 12px; color: var(--text-faint); }

.pp-template {
  display: grid;
  gap: 0;
  overflow: hidden;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--surface);
  box-shadow: var(--elevation-sm);
}
.pp-template__cover {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  min-height: 140px;
  padding: 16px;
  background: var(--bg-sunken);
  color: var(--text-faint);
  font-family: var(--font-mono);
}
.pp-template__word { font-size: 12px; letter-spacing: .12em; }
.pp-template__index { font-family: var(--font-display); font-size: 48px; line-height: 1; color: var(--accent); }
.pp-template__body { display: grid; gap: 8px; padding: 20px; }
.pp-template__title { margin: 0; font-family: var(--font-display); font-size: 18px; font-weight: 600; color: var(--text); }
.pp-template__desc { margin: 0; font-family: var(--font-body); font-size: 14px; line-height: 1.6; color: var(--text-muted); }
.pp-template__meta { display: flex; gap: 6px; }
